import React, { Component } from 'react'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'
import ReactTooltip from "react-tooltip";

class MessageForm extends Component {


    handleChange = (event) => {
        ReactTooltip.hide();
        this.props.handleMessageChange(event, this.props.messageType)
    }
    
    handleSubmit = () => {
        this.props.handleMessageSubmit(this.props.messageType)
    }
    
    
    render() {
        
            var showMessageForm;
            var showMessageSubmitButton;
            var showMessageSubmitLoadingButton;
            var message;
            var enableMessageInput;
            var enableMessageSubmitButton;
                
            switch(this.props.messageType) {

            case "sent":
                
                var showMessageForm = this.props.showSentMessagesMessageForm ? {display: 'block'} : {display: 'none'}
                var showMessageSubmitButton = this.props.showSentMessagesMessageSubmitButton ? {display: 'block'} : {display: 'none'};
                var showMessageSubmitLoadingButton = this.props.showSentMessagesMessageSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
                var message = this.props.sentMessagesMessage;
                var enableMessageInput = !this.props.enableSentMessagesMessageInput;
                var enableMessageSubmitButton = !this.props.enableSentMessagesMessageSubmitButton;
            }
          

        
        return (
          
        <Form className="messageForm" style={showMessageForm}>

        <Form.Control as="textarea"
          data-tip="Must be at least 10 characters long. You can include a full song URL. <<profileName>> will be automatically converted."
          rows="8"
          name="message"
          value={message}
          disabled={enableMessageInput}
          onChange={this.handleChange} />
        <ReactTooltip delayShow={400}/>
          
            <Button
                type="submit"
                value="Send Message!"
                disabled={enableMessageSubmitButton}
                onClick={e => {e.preventDefault(); this.handleSubmit()}}
                style={showMessageSubmitButton}>
                Submit
            </Button>
            
              <Button variant="primary" disabled style={showMessageSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                
              </Button>
          </Form>
        )
    }

}

export default MessageForm
